// Chuyển ảnh sang base64 + dựng body gọi Google Cloud Vision (DOCUMENT_TEXT_DETECTION)
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');
const trigger = $('Drive: ảnh phiếu mới').item.json;
return {
  json: {
    fileId: trigger.id,
    fileName: trigger.name,
    body: {
      requests: [{
        image: { content: base64 },
        features: [{ type: 'DOCUMENT_TEXT_DETECTION' }],
        imageContext: { languageHints: ['vi'] }
      }]
    }
  }
};

// ====== Đọc OCR Google Vision + TÁCH TRƯỜNG bằng quy tắc ======
const prep = $('Chuẩn bị ảnh (base64)').item.json;
const fileId = prep.fileId, fileName = prep.fileName;

let text = '';
try { text = $json.responses[0].fullTextAnnotation.text || ''; } catch (e) { text = ''; }

const lines = text.split('\n').map(s => s.trim()).filter(Boolean);
const T = text.replace(/\s+/g, ' ');
const pad = (s) => ('0' + String(s)).slice(-2);

// --- số cân: "9,790 kg" (phẩy = ngăn nghìn), "3,210.00 kg" ---
const parseWeight = (s) => {
  if (s == null) return null;
  let x = String(s).replace(/\s/g, '').replace(/,/g, '');
  const n = parseFloat(x.replace(/[^0-9.]/g, ''));
  return isNaN(n) ? null : Math.round(n);
};
const findKg = (label) => {
  const re = new RegExp(label + "\\s*[:\\-]?\\s*([0-9][0-9.,]*)\\s*kg", 'i');
  const m = T.match(re);
  return m ? parseWeight(m[1]) : null;
};

let tl_hang = findKg('Trọng lượng hàng') || findKg('Trọng lượng tịnh') || findKg('Net weight');
let tl_xe_vao = findKg('Trọng lượng xe vào') || findKg('xe có hàng') || findKg('Truck weight with goods');
let tl_xe_ra = findKg('Trọng lượng xe ra') || findKg('Truck weight');
if (tl_hang == null && tl_xe_vao != null && tl_xe_ra != null) tl_hang = Math.abs(tl_xe_vao - tl_xe_ra);

// --- ngày ---
let ngay = '';
const dm = T.match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
if (dm) { let y = dm[3].length === 2 ? '20' + dm[3] : dm[3]; ngay = pad(dm[1]) + '/' + pad(dm[2]) + '/' + y; }

// --- số phiếu ---
let so_phieu = (T.match(/VT[-\s]?\d+\s*\/\s*\d+/i) || [''])[0];
if (!so_phieu) { const m = T.match(/Số phiếu[^A-Z0-9]*([A-Z0-9][A-Z0-9\-\/.]{2,})/i); so_phieu = m ? m[1] : ''; }
so_phieu = so_phieu.replace(/\s+/g, '');

// --- số xe (biển VN: 77C22118, 77C-14025) ---
let so_xe = (T.match(/\b\d{2}\s?[A-Z]{1,2}[-\s]?\d{3,5}\b/) || [''])[0].replace(/[-\s]/g, '');

// --- người bán / khách hàng ---
const skip = /(DE HEUS|THẠNH HƯƠNG|THANH HUONG|VIỆT\s*-\s*PHÁP|VIET\s*-\s*PHAP|FEEDMILL|CHI NHÁNH|MST)/i;
let nguoi_ban = '';
for (const l of lines) {
  if (/(CÔNG TY|CONG TY|CTY|CP |DNTN|HỘ KINH|HKD)/i.test(l) && !skip.test(l) && l.length > 8) { nguoi_ban = l; break; }
}

// --- loại hàng / lúa ---
let loai = (T.match(/(CÁM GẠO|CAM GAO|TRẤU|TRAU|THÓC|THOC|LÚA|LUA|TẤM|TAM|GẠO|GAO|OM\s?\d+|ĐT\s?\d+|ST\s?\d+|IR\s?\d+)/i) || [''])[0].trim();

// --- kiểu cân ---
let kieu = /XUẤT|XUAT/i.test(T) ? 'XUẤT' : (/(NHẬP|NHAP|Intake)/i.test(T) ? 'NHẬP' : '');

// --- người cân ---
let nguoi_can = '';
for (let i = 0; i < lines.length; i++) {
  if (/Người cân/i.test(lines[i])) {
    const rest = lines[i].replace(/.*Người cân[:\s]*/i, '').trim();
    nguoi_can = rest || (lines[i + 1] || '');
    break;
  }
}
nguoi_can = nguoi_can.replace(/[0-9]/g, '').trim();

// --- độ ẩm ---
let do_am = '';
const am = T.match(/(?:ẩm|am)[^0-9]{0,8}([0-9]{1,2}([.,][0-9])?)\s*%/i) || T.match(/([0-9]{1,2}([.,][0-9])?)\s*%/);
if (am) do_am = am[1];

// --- kiểm tra logic số cân ---
let mathOk = true, mathNote = '';
if (tl_xe_vao != null && tl_xe_ra != null && tl_hang != null) {
  const diff = Math.abs(Math.abs(tl_xe_vao - tl_xe_ra) - tl_hang);
  if (diff > Math.max(20, tl_hang * 0.01)) { mathOk = false; mathNote = `Lệch cân: |${tl_xe_vao}-${tl_xe_ra}| khác ${tl_hang}`; }
}

const missing = [];
if (tl_hang == null) missing.push('số cân');
if (!nguoi_ban) missing.push('người bán');
if (!loai) missing.push('loại hàng');
if (!text) missing.push('OCR trống');

const conf = (missing.length === 0 && mathOk) ? 'cao' : (missing.length <= 1 ? 'trung bình' : 'thấp');
const needsReview = missing.length > 0 || !mathOk;

const reasons = [];
if (missing.length) reasons.push('Thiếu/khó đọc: ' + missing.join(', '));
if (!mathOk) reasons.push(mathNote);
reasons.push('Đối chiếu ảnh để xác nhận');

return {
  json: {
    'Thời gian xử lý': new Date().toISOString(),
    'Tên file': fileName || '',
    'Link ảnh': fileId ? `https://drive.google.com/file/d/${fileId}/view` : '',
    'Ngày phiếu': ngay,
    'Số phiếu': so_phieu,
    'Người bán / Khách hàng': nguoi_ban,
    'Loại hàng / lúa': loai,
    'Số xe': so_xe,
    'TL xe vào (kg)': tl_xe_vao != null ? tl_xe_vao : '',
    'TL xe ra (kg)': tl_xe_ra != null ? tl_xe_ra : '',
    'TL hàng (kg)': tl_hang != null ? tl_hang : '',
    'Độ ẩm (%)': do_am,
    'Kiểu cân': kieu,
    'Ghi chú chất lượng': '',
    'Người cân': nguoi_can,
    'Độ tin cậy': conf,
    'Cần kiểm tra': needsReview ? 'CÓ' : 'Không',
    'Lý do kiểm tra': reasons.join('; ')
  }
};
